WITH with_windows AS (SELECT id, device, browser, started_at, country, ROW_NUMBER() OVER (ORDER BY started_at DESC, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY device ORDER BY started_at DESC, id) AS row_seq, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at DESC, id) AS row_seq_2, ROW_NUMBER() OVER (PARTITION BY country, device ORDER BY started_at, id) AS row_seq_3 FROM sessions WHERE device = 'desktop') SELECT device, SIZE(COLLECT_SET(device)) AS num_devices, ROUND(AVG(row_seq_2), 2) AS avg_row_seq_2, PERCENTILE_APPROX(event_seq, ARRAY(0.25, 0.5, 0.75)) AS event_seq_quartiles, SORT_ARRAY(COLLECT_SET(device)) AS device_list, SIZE(COLLECT_SET(country)) AS num_countries, COUNT_IF(device = 'desktop') AS desktop_events FROM with_windows GROUP BY device HAVING SIZE(COLLECT_SET(device)) > 1 ORDER BY num_devices;
